INSERT OR REPLACE INTO article_contents (
  article_slug, lead_paragraph, sections_json, key_takeaways_json
) VALUES (
  'algoritma-doomscrolling-dan-ekonomi-atensi',
  'Hampir setiap orang pernah mengalami momen ini: berniat membuka media sosial selama lima menit sebelum tidur sekadar melihat kabar teman, lalu tersadar satu jam kemudian masih menggulir layar tanpa henti. Jari terus menarik umpan berita buruk, video singkat, dan perdebatan panas meski mata sudah perih dan hati terasa gelisah. Fenomena yang dikenal sebagai doomscrolling ini jarang terjadi karena kelemahan tekad pribadi, melainkan hasil pertemuan antara sirkuit dopamin otak purba dengan mesin optimasi Ekonomi Atensi modern.',
  '[{"heading":"Dari Kelangkaan Informasi Menuju Ekonomi Atensi","paragraphs":["Ekonom peraih Nobel Herbert Simon sejak 1971 sudah memperingatkan bahwa kelimpahan informasi otomatis menciptakan kelangkaan sesuatu yang dikonsumsi informasi tersebut, yakni perhatian manusia. Dalam lanskap digital masa kini, peringatan itu berubah menjadi model industri raksasa: semakin lama mata Anda menempel pada layar, semakin besar pendapatan iklan dan data perilaku yang dipanen platform.","Dalam Digital Minimalism, Cal Newport menjelaskan bahwa perusahaan teknologi mempekerjakan insinyur perilaku untuk menanamkan pemicu psikologis ke dalam setiap ketukan jari. Fitur gulir tanpa batas menghilangkan titik berhenti alami yang dulu hadir saat kita menutup halaman terakhir koran atau majalah. Tanpa sinyal selesai, otak tidak pernah mendapat jeda untuk bertanya apakah kita masih ingin melanjutkan.","Lebih halus lagi, tombol suka, jumlah tayangan, dan notifikasi merah memanfaatkan kebutuhan evolusioner manusia untuk diterima kelompok. Setiap jeda sepi dalam keseharian—mulai dari menunggu lampu merah hingga duduk di ruang tunggu—perlahan diambil alih oleh refleks membuka layar demi mencari pembaruan sosial instan."]},{"heading":"Jebakan Variable Reward dan Emosi Negatif","paragraphs":["Mengapa kita tetap menggulir meski konten yang muncul sering membuat cemas atau marah? Jawabannya terletak pada prinsip penguatan acak atau variable reward yang diuji psikolog B.F. Skinner dan dibahas Dan Ariely dalam Predictably Irrational. Sama seperti mesin slot kasino, setiap tarikan jari di layar menjanjikan kemungkinan kecil menemukan video lucu, kabar mengejutkan, atau validasi sosial yang memicu lonjakan dopamin antisipatif.","Sejarawan Yuval Noah Harari dalam Nexus menambahkan dimensi baru yang lebih tajam: algoritma modern tidak lagi sekadar menyalurkan informasi secara pasif, melainkan secara aktif memilih konten yang memaksimalkan keterlibatan. Dari jutaan unggahan, sistem pembelajaran mesin cepat menemukan bahwa emosi marah, takut, dan rasa terancam menahan perhatian manusia jauh lebih lama daripada ketenangan. Itulah sebabnya doomscrolling selalu terasa berat dilepaskan.","Ketika umpan berita terus menyodorkan krisis, konflik, dan kemarahan tanpa jeda, otak purba mengira bahaya sedang mengintai di sekitar kita. Akibatnya, sistem kewaspadaan terus menyala sehingga kita merasa wajib memantau layar demi rasa aman semu, padahal justru semakin cemas."],"highlightBox":{"label":"Mekanisme Mesin Slot Digital","text":"Ketidakpastian hadiah di setiap tarikan layar melepaskan dopamin lebih kuat daripada kepastian, sementara algoritma secara otomatis memprioritaskan pemicu kecemasan agar durasi tatap layar bertahan lama."}},{"heading":"Harga Kognitif di Balik Kebiasaan Menggulir","paragraphs":["Kebiasaan memberi makan otak dengan potongan informasi cepat sepanjang hari membawa biaya jangka panjang yang jarang dihitung. Dalam The Shallows, Nicholas Carr menunjukkan bahwa otak manusia bersifat plastis: jalur saraf yang terus dilatih memindai tautan singkat dan video lima belas detik perlahan kehilangan kesabaran untuk membaca argumen panjang dan berpikir kontemplatif.","Dampaknya terasa langsung pada kehidupan nyata. Ketika setiap jeda mengantre, menunggu lift, atau beristirahat di malam hari selalu diisi stimulasi layar, pikiran kehilangan ruang sunyi untuk memproses emosi dan merajut ide orisinal. Kita merasa selalu terhubung dengan seluruh dunia, tetapi justru terputus dari ketenangan batin dan fokus kerja kita sendiri.","Selain mengikis rentang perhatian, paparan cahaya biru layar dan emosi tinggi di larut malam turut merusak kualitas tidur. Keesokan harinya, kelelahan mental membuat daya tahan terhadap godaan ponsel semakin rapuh."]},{"heading":"Merebut Kembali Kendali atas Perhatian Anda","paragraphs":["Melawan tim insinyur algoritma tidak cukup hanya mengandalkan niat baik di dalam hati; kita perlu mengubah desain lingkungan fisik dan digital secara sadar. Cal Newport menyarankan untuk menghapus aplikasi umpan tak berujung dari ponsel dan mengaksesnya hanya lewat peramban komputer pada jam tertentu, sehingga gesekan kecil memutus refleks otomatis jari.","Selain itu, terapkan batas waktu malam dengan menaruh pengisi daya ponsel di luar kamar tidur dan mengganti sepuluh menit terakhir sebelum tidur dengan buku fisik atau catatan ringan. Mengubah tampilan layar ponsel menjadi hitam putih pada malam hari juga terbukti menurunkan daya tarik visual aplikasi secara signifikan.","Dengan memulihkan titik berhenti alami dalam keseharian dan mengisi waktu luang dengan aktivitas dunia nyata yang bermakna, kita mengubah posisi dari sekadar produk Ekonomi Atensi menjadi pemilik penuh atas waktu sadar kita sendiri."]}]',
  '["Doomscrolling bukan sekadar kurangnya disiplin diri, melainkan hasil desain antarmuka tanpa batas yang mengeksploitasi Ekonomi Atensi.","Ketidakpastian konten baru (variable reward) dan bias algoritma terhadap emosi takut atau marah membuat pengguna sulit berhenti menggulir.","Paparan potongan informasi cepat terus-menerus melemahkan kesabaran otak untuk membaca mendalam dan berpikir tenang.","Memasang gesekan fisik—seperti menghapus aplikasi umpan dari ponsel dan menjauhkan gawai dari kamar tidur—efektif memutus refleks otomatis."]'
);

