INSERT OR REPLACE INTO article_contents (
  article_slug, lead_paragraph, sections_json, key_takeaways_json
) VALUES (
  'eksperimen-dilema-troli',
  'Bayangkan sebuah trem berkecepatan tinggi melaju tak terkendali menuju lima pekerja yang terikat di rel utama. Anda berdiri tepat di samping tuas pengalih jalur: jika ditarik, trem akan berbelok ke rel samping dan menyelamatkan lima orang tersebut, tetapi menabrak satu pekerja yang berada di jalur cabang. Hampir sembilan puluh persen orang menjawab akan menarik tuas. Namun ketika skenario sedikit diubah—tidak ada tuas, melainkan Anda harus mendorong satu orang bertubuh besar dari atas jembatan untuk menghentikan trem—mayoritas besar tiba-tiba menolak keras. Mengapa hitungan nyawa yang sama persis menghasilkan keputusan moral yang bertolak belakang?',
  '[{"heading":"Lahirnya Teka-Teki Etika Philippa Foot","paragraphs":["Eksperimen pikiran yang kini terkenal di seluruh dunia sebagai Dilema Troli pertama kali dirumuskan filsuf Inggris Philippa Foot pada 1967 untuk membedah ketegangan abadi dalam filsafat etika. Foot ingin melihat mengapa manusia membedakan antara membiarkan sesuatu terjadi dan secara aktif menyebabkannya, bahkan ketika hasil akhirnya identik.","Dalam buku Justice, Michael Sandel menjelaskan bahwa dua jawaban berlawanan itu mencerminkan benturan antara dua aliran besar moralitas. Pilihan menarik tuas mengikuti logika utilitarianisme yang menghitung konsekuensi terbesar bagi jumlah orang terbanyak, sedangkan penolakan mendorong orang di jembatan mencerminkan etika deontologi yang menilai tindakan tertentu tetap salah secara prinsip apa pun hasilnya.","Variasi skenario jembatan yang kemudian dikembangkan filsuf Judith Jarvis Thomson membuat teka-teki ini semakin tajam: di atas kertas keduanya sama-sama menukar satu nyawa demi lima nyawa, namun nurani kita merasakan jurang perbedaan yang sangat dalam di antara keduanya."]},{"heading":"Pemindaian Otak dan Perang Dua Sistem Moral","paragraphs":["Puluhan tahun kemudian, ahli saraf Joshua Greene membawa Dilema Troli ke dalam mesin pemindai otak fMRI untuk melihat apa yang sebenarnya terjadi di kepala manusia saat menimbang kedua skenario tersebut. Hasilnya membuka tabir biologis yang memikat: skenario menarik tuas dari kejauhan mengaktifkan area korteks prefrontal yang terkait dengan penalaran rasional dan kalkulasi dingin.","Sebaliknya, membayangkan tangan sendiri mendorong tubuh manusia jatuh dari jembatan langsung menyalakan amigdala dan pusat emosi sosial secara intens. Fenomena ini selaras dengan kerangka Sistem 1 dan Sistem 2 dalam Thinking, Fast and Slow karya Daniel Kahneman serta analisis biologi perilaku dalam Behave karya Robert Sapolsky: jarak fisik dan keterlibatan langsung memicu alarm emosional purba yang melumpuhkan kalkulasi matematis.","Sejalan dengan temuan Jonathan Haidt di The Righteous Mind, ketika intuisi emosional sudah berteriak menolak tindakan mendorong dari jembatan, akal sehat langsung mencari alasan pembenaran mengapa kedua skenario itu tidak boleh disamakan."],"highlightBox":{"label":"Benturan Emosi dan Kalkulasi","text":"Ketika tindakan melukai orang lain bersifat tidak langsung lewat tuas mekanis, nalar kalkulatif mendominasi; saat kontak fisik langsung terlibat, alarm emosi purba langsung memveto pilihan utilitarian."}},{"heading":"Dari Ruang Kuliah Filsafat Menuju Algoritma Mobil Otonom","paragraphs":["Dulu Dilema Troli kerap dicibir sebagai teka-teki abstrak dosen filsafat yang mustahil terjadi di dunia nyata. Kini, perkembangan mobil swakemudi dan sistem kecerdasan buatan memaksa insinyur memprogram keputusan etis semacam itu ke dalam baris kode. Jika rem kendaraan otonom gagal di jalan sempit, ke arah mana algoritma harus membanting setir ketika tabrakan tak terhindarkan?","Survei global berskala jutaan responden bertajuk Moral Machine menunjukkan betapa rumitnya persoalan ini karena preferensi etika berbeda di tiap budaya. Namun kesamaan utamanya tetap jelas: masyarakat menuntut mesin bersikap konsisten, sementara manusia sendiri mengambil keputusan moral berdasarkan intuisi situasional yang sering berubah-ubah.","Menariknya, banyak responden menginginkan mobil otonom orang lain diprogram secara utilitarian demi keselamatan umum, tetapi untuk mobil yang mereka tumpangi sendiri, mereka tetap ingin algoritma mengutamakan keselamatan penumpang."]},{"heading":"Membaca Intuisi Etis Kita dengan Lebih Jujur","paragraphs":["Pelajaran terbesar dari Dilema Troli bukanlah mencari jawaban mana yang mutlak benar, melainkan menyadari betapa besarnya pengaruh konteks dan jarak emosional terhadap penilaian moral kita. Dalam kehidupan modern, kita lebih mudah menyetujui kebijakan atau komentar tajam di dunia maya karena jarak layar meredam alarm empati yang biasanya aktif saat bertatap muka langsung.","Ketika sebuah keputusan besar hanya diukur lewat angka di lembar kerja tanpa melihat wajah orang-orang yang terdampak, manusia berisiko mengambil langkah yang tidak akan pernah sanggup dilakukannya secara langsung.","Dengan melatih kesadaran kapan Sistem 1 bereaksi keras dan kapan kalkulasi Sistem 2 mengambil alih kendali, kita dapat mengambil keputusan etis sehari-hari—baik di tempat kerja maupun ruang publik—dengan kepala yang jauh lebih jernih dan bertanggung jawab."]}]',
  '["Dilema Troli menyingkap benturan antara etika hasil (utilitarianisme) dan etika prinsip mutlak (deontologi) dalam diri manusia.","Pemindaian otak membuktikan kontak fisik langsung memicu alarm emosi kuat yang mengalahkan hitungan matematis nyawa.","Jarak emosional dan perantara mekanis membuat manusia lebih mudah menyetujui tindakan berisiko yang tidak mungkin dilakukan langsung.","Eksperimen pikiran klasik ini kini menjadi acuan penting dalam merancang standar etika algoritma mobil otonom dan AI."]'
);

-- 8. Kisah Eksperimen #3 (sort_order: 20)
