  'jendela-overton',
  'Jendela Overton: Cara Ide Gila Menjadi Kebijakan',
  'Memahami batas spektrum gagasan yang dianggap wajar oleh publik dan bagaimana pergeseran budaya mengubah hal tabu menjadi aturan resmi.',
  'Jendela Overton',
  '["Jendela Overton","Overton Window","Wacana Publik","Batas Kewajaran"]',
  'bedah-istilah',
  4,
  'Rentang gagasan atau kebijakan yang pada suatu waktu dianggap dapat diterima dan masuk akal oleh mayoritas publik sehingga berani diperjuangkan oleh para pengambil keputusan.',
  'Joseph Overton (1990-an) · Yuval Noah Harari (2011)',
  'from-slate-950 via-violet-950 to-indigo-950',
  '/images/articles/jendela-overton.svg',
  'Bedah Istilah',
  '2026-11-28',
  '["sapiens","enlightenment-now","nexus","the-death-of-expertise"]',
  23,
  1
);
INSERT OR REPLACE INTO article_contents (
  article_slug, lead_paragraph, sections_json, key_takeaways_json
) VALUES (
  'jendela-overton',
  'Sepuluh tahun lalu, gagasan bekerja penuh dari rumah tanpa pernah menginjak kantor atau berbelanja hanya lewat siaran langsung ponsel terdengar seperti khayalan segelintir orang. Hari ini, keduanya dianggap normal dan bahkan masuk dalam peraturan kerja perusahaan besar. Perubahan serupa terjadi berulang kali dalam sejarah: hal yang dulunya ditertawakan atau dianggap terlarang perlahan bergeser menjadi wacana masuk akal hingga akhirnya disahkan sebagai hukum. Mekanisme pergeseran batas kewajaran publik inilah yang dikenal sebagai Jendela Overton.',
  '[{"heading":"Lahirnya Konsep Jendela Kewajaran Publik","paragraphs":["Konsep ini dinamai dari Joseph Overton, seorang analis kebijakan publik di Mackinac Center pada dekade 1990-an. Overton mengamati bahwa politisi dan pemimpin institusi jarang memimpin perubahan dari ruang hampa; mereka cenderung bergerak aman di dalam bingkai gagasan yang sudah dianggap wajar oleh pemilih. Di luar bingkai jendela itu, ide yang terlalu radikal berisiko memicu penolakan keras sekaligus mengakhiri karier pengusulnya.","Overton memetakan posisi suatu gagasan dalam spektrum bertingkat mulai dari tak terpikirkan, radikal, dapat diterima, masuk akal, populer, hingga akhirnya menjadi kebijakan resmi. Tugas utama gerakan sosial, ilmuwan, atau pemikir bukanlah langsung memaksa politisi memilih ide di luar jendela, melainkan menggeser jendela kewajaran masyarakat terlebih dahulu.","Begitu opini publik bergerak dan batas kewajaran bergeser, keputusan yang sebelumnya dianggap bunuh diri politik mendadak berubah menjadi pilihan populer yang diadopsi para pemimpin."]},{"heading":"Bagaimana Batas Wacana Bergeser dalam Sejarah","paragraphs":["Dalam Sapiens, Yuval Noah Harari menunjukkan bahwa hampir seluruh tatanan masyarakat modern berdiri di atas tatanan khayalan bersama yang terus berubah dari abad ke abad. Hak pilih perempuan, penghapusan perbudakan, hingga larangan merokok di ruang publik semuanya pernah berada di zona tak terpikirkan sebelum akhirnya masuk ke dalam Jendela Overton.","Steven Pinker dalam Enlightenment Now mencatat banyak kemajuan kemanusiaan bermula dari pemikir yang berani mengajukan gagasan tidak populer di zamannya. Begitu argumen berbasis bukti dan empati perlahan meresap ke percakapan sehari-hari lewat buku, jurnalisme, dan komunitas, batas toleransi publik ikut bergeser hingga sesuatu yang dulu dianggap mustahil berubah menjadi standar etika baru.","Peristiwa krisis besar seperti pandemi atau disrupsi teknologi juga sering bertindak sebagai akselerator yang menggeser Jendela Overton dalam hitungan bulan, memaksa lembaga kaku menerima cara kerja baru yang sebelumnya ditolak bertahun-tahun. Apa yang kemarin dianggap mustahil mendadak berubah menjadi standar baru."],"highlightBox":{"label":"Spektrum Jendela Overton","text":"Suatu ide berubah menjadi kebijakan bukan karena pemimpin mendadak berubah pikiran, melainkan karena perbincangan publik menggeser posisi ide tersebut dari zona radikal ke zona masuk akal."}},{"heading":"Peran Media Sosial dan Ancaman Polarisasi Cepat","paragraphs":["Di era algoritma digital, kecepatan pergeseran Jendela Overton meningkat drastis sekaligus membawa risiko baru. Dalam Nexus, Yuval Noah Harari mengingatkan bahwa jaringan informasi otomatis dapat memperluas jangkauan gagasan ekstrem hanya karena gagasan tersebut memancing keterlibatan emosional tinggi, sehingga ilusi dukungan mayoritas terbentuk sebelum diskusi sehat sempat berlangsung.","Sementara itu, Tom Nichols dalam The Death of Expertise menyoroti bagaimana tergerusnya kepercayaan pada pakar membuat standar pembuktian di ruang publik melemah. Ketika pernyataan paling keras lebih sering mendominasi layar daripada analisis tenang berbasis data, Jendela Overton berisiko bergeser bukan ke arah kemajuan, melainkan ke arah sensasionalisme yang merusak nalar kolektif.","Fenomena ini menjelaskan mengapa kelompok berkepentingan kerap sengaja melontarkan pernyataan provokatif di media sosial—bukan untuk langsung disetujui, melainkan agar ide moderat di dekatnya mulai terasa wajar. Ketika ruang publik terus dibanjiri klaim ekstrem, batas kewajaran perlahan bergeser tanpa disadari banyak orang."]},{"heading":"Menjadi Warga Kritis di Tengah Pergeseran Wacana","paragraphs":["Memahami cara kerja Jendela Overton memberi kita ketajaman membaca berita maupun strategi komunikasi di dunia kerja. Ketika melihat seseorang melontarkan usulan ekstrem yang langsung menghebohkan ruang publik, tanyakan apakah ia benar-benar ingin usulan itu diterima, atau sekadar memancing pergeseran jendela agar opsi moderat di sampingnya tampak lebih mudah disetujui.","Sebaliknya, saat Anda memperjuangkan ide perubahan yang baik namun masih terasa asing di kantor atau komunitas, bersabarlah memperluas percakapan dengan bukti nyata dan contoh kecil terlebih dahulu. Begitu batas kewajaran bergeser, perubahan besar pun dapat berjalan mulus tanpa perlawanan berarti.","Dengan menjaga standar nalar dan etika diskusi di lingkungan terdekat, kita ikut menentukan ke arah mana jendela kewajaran masyarakat bergerak di masa depan agar tetap sehat dan rasional."]}]',
  '["Jendela Overton menggambarkan rentang gagasan yang dianggap wajar dan layak didukung oleh mayoritas masyarakat pada masa tertentu.","Perubahan kebijakan besar biasanya didahului oleh pergeseran budaya, riset, dan percakapan publik yang menggerakkan posisi jendela.","Algoritma media sosial dapat mempercepat pergeseran Jendela Overton baik ke arah kemajuan sosial maupun ke arah ekstremisme emosional.","Mengenali taktik penggeseran batas wacana membantu kita berpikir lebih jernih menghadapi isu viral dan merancang strategi perubahan bertahap."]'
);

